class Solution {
    vector<int> alias_;
    vector<double> prob_;
    int n;
    mt19937 rng;
    uniform_int_distribution<int> intDist;
    uniform_real_distribution<double> realDist;
public:
    Solution(vector<int>& w) {
        n = (int)w.size();
        alias_.assign(n, 0);
        prob_.assign(n, 0.0);
        rng.seed(random_device{}());

        double sum = 0.0;
        for (int x : w) sum += (double)x;

        vector<double> p(n);
        for (int i = 0; i < n; i++) {
            p[i] = (double)w[i] * (double)n / sum;
        }

        vector<int> small, large;
        small.reserve(n);
        large.reserve(n);
        for (int i = 0; i < n; i++) {
            if (p[i] < 1.0) small.push_back(i);
            else large.push_back(i);
        }

        while (!small.empty() && !large.empty()) {
            int l = small.back(); small.pop_back();
            int g = large.back(); large.pop_back();
            prob_[l] = p[l];
            alias_[l] = g;
            p[g] = p[g] + p[l] - 1.0;
            if (p[g] < 1.0) small.push_back(g);
            else large.push_back(g);
        }

        while (!large.empty()) {
            int g = large.back(); large.pop_back();
            prob_[g] = 1.0;
        }
        while (!small.empty()) {
            int l = small.back(); small.pop_back();
            prob_[l] = 1.0;
        }

        intDist = uniform_int_distribution<int>(0, n - 1);
        realDist = uniform_real_distribution<double>(0.0, 1.0);
    }

    int pickIndex() {
        int i = intDist(rng);
        double r = realDist(rng);
        if (r < prob_[i]) return i;
        return alias_[i];
    }
};
